let academicPartials=readStore('evalpro-partials-v1',[]),selectedPartialId=null,editingRecordId=null,registrationGender='neutral';
if(!Array.isArray(academicPartials)||!academicPartials.length){academicPartials=[{id:'partial-1',name:'Parcial 1',params:bookParams.map(p=>({...p,id:p.id||makeId()}))}];writeStore('evalpro-partials-v1',academicPartials)}
academicPartials=academicPartials.map((part,index)=>({...part,id:part.id||`partial-${index+1}`,name:String(part.name||`Parcial ${index+1}`),params:Array.isArray(part.params)&&part.params.length?part.params.map(p=>({...p,id:p.id||makeId()})):bookParams.map(p=>({...p,id:p.id||makeId()}))}));
selectedPartialId=academicPartials[0].id;bookParams=academicPartials[0].params;
let migratedRecords=false;roster.forEach(p=>{(p.records||[]).forEach(record=>{if(!record.partialId){record.partialId=selectedPartialId;migratedRecords=true}})});if(migratedRecords)writeStore('evalpro-roster-v1',roster);
function currentPartial(){return academicPartials.find(p=>p.id===selectedPartialId)||academicPartials[0]}
function renderPartialSelectors(){const config=$('partialSelector'),activity=$('recordPartial');if(!config||!activity)return;const options=academicPartials.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');config.innerHTML=options;activity.innerHTML=options;config.value=selectedPartialId;activity.value=selectedPartialId}
function selectPartial(id){if(!academicPartials.some(p=>p.id===id))return;selectedPartialId=id;bookParams=currentPartial().params;renderPartialSelectors();renderBookParams();renderCategoryOptions();renderRoster();if(selectedStudentId)openFile(selectedStudentId)}
function selectRecordPartial(id){if(!academicPartials.some(p=>p.id===id))return;selectedPartialId=id;bookParams=currentPartial().params;$('partialSelector').value=id;renderBookParams();renderCategoryOptions()}
function createPartial(){const name=$('newPartialName').value.trim();if(!name){toast('Escribe el nombre del parcial.');return}if(academicPartials.some(p=>normalizeName(p.name)===normalizeName(name))){toast('Ya existe un parcial con ese nombre.');return}const params=currentPartial().params.map(p=>({...p,id:makeId()}));const partial={id:makeId(),name,params};academicPartials.push(partial);selectedPartialId=partial.id;bookParams=partial.params;$('newPartialName').value='';persistPartials();renderPartialSelectors();renderBookParams();renderCategoryOptions();renderRoster();toast(`${name} creado; ajusta sus ponderaciones antes de guardar.`)}
function persistPartials(){writeStore('evalpro-partials-v1',academicPartials);writeStore('evalpro-book-params-v1',currentPartial().params)}
function renderBookParams(){const part=currentPartial();if(!part)return;bookParams=part.params;const box=$('bookParams');box.innerHTML=bookParams.map((p,i)=>`<div class="param-row book-param-row"><div class="field param-name"><label class="param-label">${categorySvg(p.id,p.name)}<span>Parámetro</span></label><input data-book-i="${i}" data-book-k="name" value="${esc(p.name)}" placeholder="Ej. Tareas"></div><div class="field"><label>Peso (%)</label><input data-book-i="${i}" data-book-k="weight" type="number" min="0" max="100" step="0.1" value="${p.weight}"></div><button class="btn btn-danger remove-param" onclick="removeBookParam(${i})" aria-label="Quitar parámetro">Quitar</button></div>`).join('');box.querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{const p=bookParams[+el.dataset.bookI],key=el.dataset.bookK;p[key]=key==='name'?el.value:(parseFloat(el.value)||0);showBookWeights()}));showBookWeights();renderCategoryOptions()}
function renderCategoryOptions(){const select=$('recordCategory'),previous=select.value,params=currentPartial().params;select.innerHTML=params.length?params.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join(''):'<option value="">Agrega un parámetro</option>';if(params.some(p=>p.id===previous))select.value=previous;updateCategoryIcon()}
function categorySvg(id,name=''){const key=`${id} ${name}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let paths;if(key.includes('tarea')||key.includes('clipboard'))paths='<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V3h6v1M8 10h8M8 14h8M8 18h5"/>';else if(key.includes('trabaj')||key.includes('proyecto'))paths='<rect x="3" y="6" width="18" height="14" rx="2"/><path d="M8 6V4h8v2M3 11h18M10 11v2h4v-2"/>';else if(key.includes('examen')||key.includes('quiz'))paths='<path d="M7 3h10a2 2 0 0 1 2 2v16H5V5a2 2 0 0 1 2-2Z"/><path d="m8 12 2.5 2.5L16 9M8 7h8"/>';else if(key.includes('particip'))paths='<path d="M8 11V5a2 2 0 0 1 4 0v5-2a2 2 0 0 1 4 0v2-1a2 2 0 0 1 4 0v6a6 6 0 0 1-6 6h-2a6 6 0 0 1-4-2l-4-4a2 2 0 0 1 3-3l2 2"/>';else if(key.includes('cuaderno')||key.includes('libro'))paths='<path d="M3 5.5A2.5 2.5 0 0 1 5.5 3H11v17H5.5A2.5 2.5 0 0 0 3 22V5.5ZM21 5.5A2.5 2.5 0 0 0 18.5 3H13v17h5.5A2.5 2.5 0 0 1 21 22V5.5Z"/>';else paths='<path d="M20 7 10 17l-5-5"/><path d="M20 12v6a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h9"/>';return `<svg class="category-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`}
function updateCategoryIcon(){const icon=$('categoryIcon'),param=currentPartial().params.find(p=>p.id===$('recordCategory').value);if(icon)icon.innerHTML=param?categorySvg(param.id,param.name):''}
function showBookWeights(){const total=bookParams.reduce((sum,p)=>sum+(+p.weight||0),0),hint=$('bookWeightHint');hint.textContent=`${currentPartial().name} · Ponderación: ${total.toFixed(1)}%${Math.abs(total-100)<.001?' — lista para guardar.':' — ajusta los pesos para que sumen 100%.'}`;hint.classList.toggle('invalid',Math.abs(total-100)>.001)}
function addBookParam(){bookParams.push({id:makeId(),name:'Nuevo parámetro',weight:0});renderBookParams()}
function removeBookParam(i){if(bookParams.length<=1){toast('Debe quedar al menos un parámetro.');return}bookParams.splice(i,1);renderBookParams()}
function saveBookParams(){const total=bookParams.reduce((sum,p)=>sum+(+p.weight||0),0);if(!bookParams.length||bookParams.some(p=>!p.name.trim()||p.weight<0)||Math.abs(total-100)>.001){toast('Completa los nombres y ajusta los pesos para sumar 100%.');return}persistPartials();renderBookParams();renderRoster();if(selectedStudentId)openFile(selectedStudentId);toast(`Parámetros de ${currentPartial().name} guardados`)}
function studentAverage(pupil){const partialGrades=academicPartials.map(part=>{const params=part.params||[],records=pupil.records||[],scores=params.map(param=>{const items=records.filter(r=>r.partialId===part.id&&r.categoryId===param.id&&Number(r.max)>0);if(!items.length)return null;return{weight:+param.weight,grade:items.reduce((sum,r)=>sum+(+r.score/+r.max)*10,0)/items.length}}).filter(Boolean),weightTotal=scores.reduce((sum,s)=>sum+s.weight,0);return weightTotal?scores.reduce((sum,s)=>sum+s.grade*s.weight,0)/weightTotal:null}).filter(grade=>grade!==null);return partialGrades.length?partialGrades.reduce((sum,grade)=>sum+grade,0)/partialGrades.length:null}
function selectGenderClass(gender){return gender==='male'?'avatar-male':gender==='female'?'avatar-female':'avatar-neutral'}
function cycleRegistrationAvatar(){registrationGender=registrationGender==='neutral'?'male':registrationGender==='male'?'female':'neutral';const button=$('newStudentAvatar');button.className=`avatar avatar-picker ${selectGenderClass(registrationGender)}`;button.textContent=avatarEmoji(registrationGender);button.setAttribute('aria-label',`Avatar ${registrationGender}; pulsa para cambiar`)}
function cycleGender(id,gender){const pupil=roster.find(p=>p.id===id);if(!pupil)return;pupil.gender=gender|| (pupil.gender==='neutral'||!pupil.gender?'male':pupil.gender==='male'?'female':'neutral');writeStore('evalpro-roster-v1',roster);renderRoster();if(selectedStudentId===id)openFile(id)}
function updateGender(id,gender){cycleGender(id,gender)}
function editStudentName(id){const pupil=roster.find(student=>student.id===id);if(!pupil)return;const updated=prompt('Edita el nombre completo del alumno:',pupil.name);if(updated===null)return;const name=updated.trim();if(!name){toast('El nombre no puede quedar vacío.');return}if(roster.some(student=>student.id!==id&&normalizeName(student.name)===normalizeName(name))){toast('Ya existe otro alumno con ese nombre.');return}pupil.name=name;students.forEach(result=>{if(result.studentId===id)result.name=name});writeStore('evalpro-roster-v1',roster);writeStore('evalpro-exam-students-v1',students);renderRoster();renderAll();if(selectedStudentId===id)openFile(id);toast('Nombre del alumno actualizado')}
function addRosterStudent(){const name=$('newStudentName').value.trim();if(!name){toast('Escribe el nombre del alumno.');return}if(roster.some(p=>normalizeName(p.name)===normalizeName(name))){toast('Ese alumno ya está en el registro.');return}const pupil=getOrCreateStudent(name,registrationGender);enrollInSelectedSubject(pupil);writeStore('evalpro-roster-v1',roster);$('newStudentName').value='';registrationGender='neutral';$('newStudentAvatar').className='avatar avatar-picker avatar-neutral';$('newStudentAvatar').textContent=avatarEmoji(registrationGender);renderRoster();renderStudentOptions();openFile(pupil.id);toast(`${name} guardado en el registro semestral`)}
function renderRoster(){const list=$('rosterList');if(!list)return;const visible=filteredRoster();list.innerHTML=visible.length?`<div class="table-wrap roster-table"><table><thead><tr><th>Alumno · toca su avatar para cambiarlo</th><th>Materias</th><th>Promedio</th><th>Registros</th><th>Expediente</th><th>Acciones</th></tr></thead><tbody>${visible.map(p=>{const average=studentAverage(p),names=subjects.filter(s=>(s.studentIds||[]).includes(p.id)).map(s=>s.name);return `<tr><td><span class="pupil-cell"><button type="button" class="avatar avatar-click ${selectGenderClass(p.gender)}" onclick="updateGender('${esc(p.id)}')" aria-label="Cambiar avatar de ${esc(p.name)}" title="Pulsa para cambiar el avatar">${avatarEmoji(p.gender)}</button><b>${esc(p.name)}</b></span></td><td>${names.length?names.map(esc).join(', '):'—'}</td><td>${average===null?'—':average.toFixed(2)+'/10'}</td><td>${(p.records||[]).length}</td><td><button class="btn btn-sm" onclick="openFile('${esc(p.id)}')">Abrir</button></td><td class="roster-actions">${selectedSubjectId?`<button class="btn btn-orange btn-sm" onclick="removeFromSubject('${esc(p.id)}')">Quitar materia</button>`:''}<button class="btn btn-sm" onclick="editStudentName('${esc(p.id)}')">Editar nombre</button><button class="btn btn-danger btn-sm" onclick="removeRosterStudent('${esc(p.id)}')">Borrar alumno</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${roster.length?'No hay alumnos que coincidan con estos filtros.':'Todavía no hay alumnos. Registra el primero aquí o desde la pestaña Examen.'}</div>`;renderStudentOptions();renderSubjectMemberOptions();updateFilterSummary()}
function clearRecordForm(){editingRecordId=null;$('recordTitle').value='';$('recordScore').value='';$('recordMax').value='10';$('recordNote').value='';$('saveRecordButton').textContent='＋ Guardar en expediente';$('cancelRecordButton').hidden=true}
function cancelRecordEdit(){clearRecordForm();toast('Edición cancelada')}
function addRecord(){const wasEditing=Boolean(editingRecordId),studentId=$('recordStudent').value,pupil=roster.find(s=>s.id===studentId),part=academicPartials.find(p=>p.id===$('recordPartial').value),param=part?.params.find(p=>p.id===$('recordCategory').value),title=$('recordTitle').value.trim(),score=parseFloat($('recordScore').value),max=parseFloat($('recordMax').value);if(!pupil){toast('Registra o selecciona un alumno.');return}if(!part||!param){toast('Selecciona un parcial y un parámetro configurado.');return}if(!title){toast('Escribe el nombre de la actividad.');return}if(!Number.isFinite(score)||!Number.isFinite(max)||max<=0||score<0||score>max){toast(`La calificación debe estar entre 0 y ${max||'el máximo'}.`);return}pupil.records=pupil.records||[];const record={id:editingRecordId||makeId(),partialId:part.id,categoryId:param.id,categoryName:param.name,title,date:$('recordDate').value||today(),score,max,note:$('recordNote').value.trim()};if(wasEditing){const index=pupil.records.findIndex(r=>r.id===editingRecordId);if(index<0){toast('No se encontró el registro para editar.');return}pupil.records[index]=record}else{pupil.records.push(record)}writeStore('evalpro-roster-v1',roster);clearRecordForm();selectedStudentId=pupil.id;renderRoster();openFile(pupil.id);toast(wasEditing?'Registro actualizado':'Actividad guardada en el expediente')}
function editRecord(studentId,recordId){const pupil=roster.find(s=>s.id===studentId),record=pupil?.records.find(r=>r.id===recordId);if(!pupil||!record)return;editingRecordId=record.id;selectedStudentId=pupil.id;selectedPartialId=academicPartials.some(p=>p.id===record.partialId)?record.partialId:academicPartials[0].id;bookParams=currentPartial().params;renderPartialSelectors();renderBookParams();renderCategoryOptions();let studentOption=[...$('recordStudent').options].find(o=>o.value===pupil.id);if(!studentOption){studentOption=new Option(pupil.name,pupil.id,true,true);$('recordStudent').add(studentOption)}$('recordStudent').value=pupil.id;$('recordPartial').value=selectedPartialId;$('recordCategory').value=record.categoryId;$('recordTitle').value=record.title;$('recordDate').value=record.date||today();$('recordScore').value=record.score;$('recordMax').value=record.max;$('recordNote').value=record.note||'';$('saveRecordButton').textContent='Guardar cambios';$('cancelRecordButton').hidden=false;updateCategoryIcon();document.querySelector('.activity-card').scrollIntoView({behavior:'smooth',block:'center'})}
function deleteRecord(studentId,recordId){const pupil=roster.find(s=>s.id===studentId);if(!pupil)return;pupil.records=pupil.records.filter(r=>r.id!==recordId);if(editingRecordId===recordId)clearRecordForm();writeStore('evalpro-roster-v1',roster);renderRoster();openFile(studentId);toast('Registro eliminado')}
function openFile(id){const pupil=roster.find(s=>s.id===id);if(!pupil)return;selectedStudentId=id;$('studentFile').hidden=false;$('fileAvatar').className=`avatar avatar-large ${selectGenderClass(pupil.gender)}`;$('fileAvatar').textContent=avatarEmoji(pupil.gender);$('fileName').textContent=`Expediente · ${pupil.name}`;const average=studentAverage(pupil);$('fileSummary').textContent=`${(pupil.records||[]).length} registros · Promedio general de parciales: ${average===null?'Sin calificaciones':average.toFixed(2)+'/10'}`;$('fileStats').innerHTML=academicPartials.map(part=>{const paramGrades=part.params.map(param=>{const items=(pupil.records||[]).filter(r=>r.partialId===part.id&&r.categoryId===param.id&&+r.max>0);return items.length?{weight:+param.weight,grade:items.reduce((sum,r)=>sum+(+r.score/+r.max)*10,0)/items.length}:null}).filter(Boolean),totalWeight=paramGrades.reduce((sum,g)=>sum+g.weight,0),grade=totalWeight?paramGrades.reduce((sum,g)=>sum+g.grade*g.weight,0)/totalWeight:null,count=(pupil.records||[]).filter(r=>r.partialId===part.id).length;return `<div class="stat partial-stat"><strong>${grade===null?'—':grade.toFixed(2)}</strong><span>${esc(part.name)} · ${count} registro(s)</span></div>`}).join('');const records=[...(pupil.records||[])].sort((a,b)=>b.date.localeCompare(a.date));$('recordList').innerHTML=records.length?records.map(r=>{const part=academicPartials.find(p=>p.id===r.partialId),param=part?.params.find(p=>p.id===r.categoryId),icon=categorySvg(r.categoryId,param?.name||r.categoryName||'');return `<article class="record-item"><div class="record-main"><span class="record-type">${icon}${esc(param?.name||r.categoryName||'Registro')} · ${esc(part?.name||'Sin parcial')}</span><b>${esc(r.title)}</b><small>${esc(r.date||'Sin fecha')}${r.note?' · '+esc(r.note):''}</small></div><strong class="record-score">${r.scoreUnit==="partial-percent"?`${Number(r.score).toFixed(2)}% del parcial`:`${Number(r.score).toFixed(2)} / ${Number(r.max).toFixed(2)}`}</strong><div class="record-actions no-print"><button class="btn btn-sm" onclick="editRecord('${esc(pupil.id)}','${esc(r.id)}')">Editar</button><button class="btn btn-danger btn-sm" onclick="deleteRecord('${esc(pupil.id)}','${esc(r.id)}')">Quitar</button></div></article>`}).join(''):'<div class="empty">Aún no hay actividades en este expediente.</div>';if($('recordStudent'))$('recordStudent').value=id}
function printStudentFile(){if(!selectedStudentId){toast('Abre un expediente antes de imprimir.');return}document.body.classList.add('printing-student-file');const clean=()=>{document.body.classList.remove('printing-student-file');window.removeEventListener('afterprint',clean)};window.addEventListener('afterprint',clean,{once:true});window.print();setTimeout(clean,1200)}
function clearSelectedStudent(){ $('studentFile').hidden=true;selectedStudentId=null;clearRecordForm()}
function toggleTheme(){const root=document.documentElement,next=root.dataset.theme==='light'?'dark':'light';root.dataset.theme=next;localStorage.setItem('evalpro-theme',next);$('themeBtn').textContent=next==='light'?'🌙 Modo oscuro':'☀️ Modo claro';if(students.length)drawCharts(filteredExam())}
