// Configuración de parámetros por materia y parcial, además del cálculo de tareas.
var selectedConfigSubjectId=selectedSubjectId||subjects[0]?.id||'';
function configSubjectId(){return selectedConfigSubjectId||''}
function getPartParams(part,subjectId=configSubjectId(),create=true){if(!part)return[];part.subjectParams=part.subjectParams||{};const key=subjectId||'__general__';if(!part.subjectParams[key]&&create){const base=part.params||[];part.subjectParams[key]=base.map(p=>({...p,id:p.id||makeId(),max:Number(p.max)||10}));}return part.subjectParams[key]||part.params||[]}
function recordSubjectId(){return $('recordSubject')?.value||''}
function recordParams(part=currentPartial(),subjectId=recordSubjectId()){return getPartParams(part,subjectId||'__general__')}
function renderConfigSubjects(){const select=$('configSubject');if(!select)return;const old=selectedConfigSubjectId;select.innerHTML='<option value="">General (sin materia)</option>'+subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');selectedConfigSubjectId=subjects.some(s=>s.id===old)?old:(subjects[0]?.id||'');select.value=selectedConfigSubjectId}
function selectConfigSubject(id){selectedConfigSubjectId=id||'';bookParams=getPartParams(currentPartial(),selectedConfigSubjectId);renderBookParams();renderRecordSubjects();refreshRecordParameterInfo()}
function selectPartial(id){if(!academicPartials.some(p=>p.id===id))return;selectedPartialId=id;bookParams=getPartParams(currentPartial(),selectedConfigSubjectId);renderPartialSelectors();renderBookParams();renderCategoryOptions();renderRoster();if(selectedStudentId)openFile(selectedStudentId);refreshRecordParameterInfo()}
function selectRecordPartial(id){if(!academicPartials.some(p=>p.id===id))return;selectedPartialId=id;bookParams=getPartParams(currentPartial(),recordSubjectId());$('partialSelector').value=id;renderBookParams();renderCategoryOptions();refreshRecordParameterInfo()}
function renderPartialSelectors(){const config=$('partialSelector'),activity=$('recordPartial');if(!config||!activity)return;const options=academicPartials.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');config.innerHTML=options;activity.innerHTML=options;config.value=selectedPartialId;activity.value=selectedPartialId}
function createPartial(){const name=$('newPartialName').value.trim();if(!name){toast('Escribe el nombre del parcial.');return}if(academicPartials.some(p=>normalizeName(p.name)===normalizeName(name))){toast('Ya existe un parcial con ese nombre.');return}const source=getPartParams(currentPartial(),selectedConfigSubjectId),params=source.map(p=>({...p,id:makeId()}));const partial={id:makeId(),name,params,subjectParams:{}};partial.subjectParams[selectedConfigSubjectId||'__general__']=params;academicPartials.push(partial);selectedPartialId=partial.id;bookParams=params;$('newPartialName').value='';persistPartials();renderPartialSelectors();renderBookParams();renderCategoryOptions();renderRoster();toast(`${name} creado; ajusta sus ponderaciones antes de guardar.`)}
function persistPartials(){writeStore('evalpro-partials-v1',academicPartials);writeStore('evalpro-book-params-v1',getPartParams(currentPartial(),selectedConfigSubjectId))}
function renderBookParams(){const part=currentPartial();if(!part)return;bookParams=getPartParams(part,selectedConfigSubjectId);const box=$('bookParams');box.innerHTML=bookParams.map((p,i)=>`<div class="param-row book-param-row"><div class="field param-name"><label class="param-label">${categorySvg(p.id,p.name)}<span>Parámetro</span></label><input data-book-i="${i}" data-book-k="name" value="${esc(p.name)}" placeholder="Ej. Tareas"></div><div class="field"><label>Peso (%)</label><input data-book-i="${i}" data-book-k="weight" type="number" min="0" max="100" step="0.1" value="${p.weight}"></div><div class="field"><label>Máximo</label><input data-book-i="${i}" data-book-k="max" type="number" min="0.01" step="any" value="${Number(p.max)||10}"></div><button class="btn btn-danger remove-param" onclick="removeBookParam(${i})" aria-label="Quitar parámetro">Quitar</button></div>`).join('');box.querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{const p=bookParams[+el.dataset.bookI],key=el.dataset.bookK;p[key]=key==='name'?el.value:(parseFloat(el.value)||0);showBookWeights();refreshRecordParameterInfo()}));showBookWeights();renderCategoryOptions()}
function renderCategoryOptions(){const select=$('recordCategory'),previous=select.value,params=recordParams();select.innerHTML=params.length?params.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join(''):'<option value="">Agrega un parámetro</option>';if(params.some(p=>p.id===previous))select.value=previous;updateCategoryIcon();syncTaskEntry()}
function updateCategoryIcon(){const icon=$('categoryIcon'),param=recordParams().find(p=>p.id===$('recordCategory').value);if(icon)icon.innerHTML=param?categorySvg(param.id,param.name):''}
function showBookWeights(){const total=bookParams.reduce((sum,p)=>sum+(+p.weight||0),0),hint=$('bookWeightHint');if(!hint)return;hint.textContent=`${currentPartial().name} · ${subjects.find(s=>s.id===selectedConfigSubjectId)?.name||'General'} · Ponderación: ${total.toFixed(1)}%${Math.abs(total-100)<.001?' — lista para guardar.':' — ajusta los pesos para que sumen 100%.'}`;hint.classList.toggle('invalid',Math.abs(total-100)>.001)}
function addBookParam(){bookParams.push({id:makeId(),name:'Nuevo parámetro',weight:0,max:10});renderBookParams()}
function removeBookParam(i){if(!confirm('¿Estás seguro de eliminar el parámetro?'))return;if(bookParams.length<=1){toast('Debe quedar al menos un parámetro.');return}bookParams.splice(i,1);renderBookParams()}
function saveBookParams(){const total=bookParams.reduce((sum,p)=>sum+(+p.weight||0),0);if(!bookParams.length||bookParams.some(p=>!p.name.trim()||p.weight<0||(+p.max||0)<=0)||Math.abs(total-100)>.001){toast('Completa los nombres, puntajes máximos y ajusta los pesos para sumar 100%.');return}const part=currentPartial();part.subjectParams=part.subjectParams||{};part.subjectParams[selectedConfigSubjectId||'__general__']=bookParams;persistPartials();renderBookParams();renderRoster();if(selectedStudentId)openFile(selectedStudentId);refreshRecordParameterInfo();toast(`Parámetros de ${currentPartial().name} guardados`)}
