function refreshContribution(){const target=$('taskContribution'),param=recordParams().find(p=>p.id===$('recordCategory')?.value);if(!target||!param)return;const score=Number($('recordScore')?.value);target.textContent=`${param.name}: pesa ${Number(param.weight||0)}% del parcial · aporte registrado ${Number.isFinite(score)?score.toFixed(2):'0.00'}% del parcial.`}
function addRecord(){const wasEditing=Boolean(editingRecordId),studentId=$('recordStudent').value,pupil=roster.find(s=>s.id===studentId),part=academicPartials.find(p=>p.id===$('recordPartial').value),subjectId=recordSubjectId(),param=recordParams(part,subjectId).find(p=>p.id===$('recordCategory').value),title=$('recordTitle').value.trim(),isTask=normalizeName(param?.name||'').includes('tarea'),max=Number(param?.weight)||0,score=Number($('recordScore').value),deliveredInput=$('tasksDelivered').value,totalInput=$('tasksTotal').value,hasTaskCounts=deliveredInput!==''||totalInput!=='';if(!pupil){toast('Registra o selecciona un alumno.');return}if(!part||!param){toast('Selecciona un parcial y un parámetro configurado.');return}if(!title){toast('Escribe el nombre de la actividad.');return}if(max<=0){toast('Este parámetro debe tener un peso mayor que 0%.');return}if(isTask&&hasTaskCounts&&(!Number.isInteger(Number(deliveredInput))||!Number.isInteger(Number(totalInput))||Number(totalInput)<1||Number(deliveredInput)<0||Number(deliveredInput)>Number(totalInput))){toast('Indica las tareas entregadas y las tareas totales; las entregadas no pueden superar el total.');return}if(!Number.isFinite(score)||score<0||score>max){toast(`La calificación del parámetro debe estar entre 0% y ${max}% del parcial.`);return}pupil.records=pupil.records||[];const record={id:editingRecordId||makeId(),partialId:part.id,subjectId,subjectName:subjects.find(s=>s.id===subjectId)?.name||'General',categoryId:param.id,categoryName:param.name,title,date:$('recordDate').value||today(),score,max,scoreUnit:'partial-percent',note:$('recordNote').value.trim(),...(isTask&&hasTaskCounts?{tasksDelivered:Number(deliveredInput),tasksTotal:Number(totalInput)}:{})};if(wasEditing){const i=pupil.records.findIndex(r=>r.id===editingRecordId);if(i<0){toast('No se encontró el registro para editar.');return}pupil.records[i]=record}else pupil.records.push(record);writeStore('evalpro-roster-v1',roster);clearRecordForm();selectedStudentId=pupil.id;renderRoster();openFile(pupil.id);toast(wasEditing?'Registro actualizado':'Actividad guardada en el expediente')}

function clearRecordForm(){editingRecordId=null;$('recordTitle').value='';$('recordScore').value='';$('recordMax').value='10';$('recordNote').value='';$('tasksDelivered').value='';$('tasksTotal').value='';$('saveRecordButton').textContent='＋ Guardar en expediente';$('cancelRecordButton').hidden=true;const task=normalizeName(recordParams().find(p=>p.id===$('recordCategory').value)?.name||'').includes('tarea');if(task)calculateTaskGrade();else refreshContribution()}
function editRecord(studentId,recordId){const pupil=roster.find(s=>s.id===studentId),record=pupil?.records.find(r=>r.id===recordId);if(!pupil||!record)return;editingRecordId=record.id;selectedStudentId=pupil.id;selectedPartialId=academicPartials.some(p=>p.id===record.partialId)?record.partialId:academicPartials[0].id;renderPartialSelectors();let option=[...$('recordStudent').options].find(o=>o.value===pupil.id);if(!option){option=new Option(pupil.name,pupil.id,true,true);$('recordStudent').add(option)}$('recordStudent').value=pupil.id;renderRecordSubjects(record.subjectId);$('recordPartial').value=selectedPartialId;const param=recordParams(currentPartial(),record.subjectId).find(p=>p.id===record.categoryId);$('recordCategory').value=record.categoryId;bookParams=recordParams(currentPartial(),record.subjectId);renderCategoryOptions();$('recordCategory').value=record.categoryId;$('recordTitle').value=record.title;$('recordDate').value=record.date||today();const contribution=record.scoreUnit==='partial-percent'?Number(record.score):(Number(record.score)/Number(record.max||10))*(Number(param?.weight)||0);$('recordScore').value=Number.isFinite(contribution)?contribution.toFixed(2):'';$('recordMax').value=Number(param?.weight)||0;$('recordNote').value=record.note||'';$('tasksDelivered').value=record.tasksDelivered??'';$('tasksTotal').value=record.tasksTotal??'';$('saveRecordButton').textContent='Guardar cambios';$('cancelRecordButton').hidden=false;updateCategoryIcon();syncTaskEntry();refreshRecordParameterInfo();document.querySelector('.activity-card').scrollIntoView({behavior:'smooth',block:'center'})}
